        // Save the updated item
        await saveMetaItem(ctx, found, itemType);

        // AC: @trait-shadow-commit ac-1
        await commitIfShadow(
          ctx.shadow,
          `meta-set-${itemType}`,
          found._ulid.substring(0, 8),
