/**
 * Meta CLI commands for interacting with meta-spec.
 *
 * AC-meta-manifest-1: kspec meta show outputs summary
 * AC-meta-manifest-2: kspec validate includes meta line
 * AC-meta-manifest-3: kspec validate shows meta errors with prefix
 * AC-agent-1: kspec meta agents outputs table
 * AC-agent-2: kspec meta agents --json outputs JSON
 */

import chalk from "chalk";
import Table from "cli-table3";
import type { Command } from "commander";
import { ulid } from "ulid";
import { markMutating } from "../command-annotations.js";
import {
  type Agent,
  type Convention,
  createObservation,
  createTask,
  deleteInboxItem,
  deleteMetaItem,
  findInboxItemByRef,
  getMetaStats,
  initContext,
  type LoadedTask,
  loadAllItems,
  loadAllTasks,
  loadInboxItems,
  loadMetaContext,
  loadSessionContext,
  type MetaContext,
  type Observation,
  ReferenceIndex,
  resolveMetaRef,
  saveMetaItem,
  saveObservation,
  saveSessionContext,
  saveTask,
  type Workflow,
} from "../../parser/index.js";
