          ctx,
          item,
          type as "agent" | "workflow" | "convention",
        );

        // AC: @trait-shadow-commit ac-1
        await commitIfShadow(
          ctx.shadow,
          `meta-add-${type}`,
          itemUlid.substring(0, 8),
          "id" in item ? item.id : "domain" in item ? item.domain : undefined,
