    const agentsFile = path.join(metaDir, 'agents.yaml');
    await fs.writeFile(
      agentsFile,
      `agents:
  - _ulid: 01KF8850000000000000000001
    id: include-agent-1
    name: Include Agent 1
    description: Agent from included file
    capabilities:
      - code
    tools:
      - git
    conventions: []

