  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();
  });

  afterEach(async () => {
    await cleanupTempDir(tempDir);
  });

  // AC: @workflow-definitions ac-workflow-1
  it('should output table with ID, Trigger, Steps columns', () => {
